const item = $input.first().json;
const data = item.body && typeof item.body === 'object' ? item.body : item;

if (data.website && String(data.website).trim() !== '') {
  return [{ json: { _phase: 'spam', _received_at: new Date().toISOString() } }];
}

const required = ['prenom', 'nom', 'email', 'secteur', 'budget', 'description', 'rgpd'];
const missing = required.filter((f) => !data[f] || (typeof data[f] === 'string' && !String(data[f]).trim()));
if (missing.length) {
  return [{ json: { _phase: 'invalid', _error: 'missing_fields', _missing: missing } }];
}

const email = String(data.email || '');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  return [{ json: { _phase: 'invalid', _error: 'invalid_email' } }];
}

const projets = Array.isArray(data.projet) ? data.projet : data.projet ? [data.projet] : [];
if (!projets.length) {
  return [{ json: { _phase: 'invalid', _error: 'missing_projet' } }];
}

let score = 0;
const budget = String(data.budget || '');
if (/gt25k/.test(budget)) score += 40;
else if (/10k-25k/.test(budget)) score += 30;
else if (/5k-10k/.test(budget)) score += 20;
else if (/2k-5k/.test(budget)) score += 10;

if (data.urgence === 'asap') score += 25;
else if (data.urgence === '1-3m') score += 15;
else if (data.urgence === '3-6m') score += 5;

if (projets.length >= 3) score += 25;
else if (projets.length === 2) score += 15;
else if (projets.length === 1) score += 5;

if (data.description && String(data.description).length > 300) score += 10;
if (data.entreprise) score += 5;
if (data.telephone) score += 5;
if (data.site_actuel) score += 5;

let tier = 'cold';
if (score >= 75) tier = 'hot';
else if (score >= 45) tier = 'warm';

const slackEmoji = tier === 'hot' ? '🔥' : tier === 'warm' ? '⚡' : '❄️';

const payload = {
  ...data,
  projet: projets,
  _phase: 'lead',
  _server_score: score,
  _tier: tier,
  _projets_str: projets.join(', '),
  _received_at: new Date().toISOString(),
  _slack_emoji: slackEmoji,
};

return [{ json: payload }];
